9	/* ============================ Cây xanh & đèn đường ============================ */
10	export function buildTrees() {
11	  const round: [number, number][] = [], palms: [number, number][] = [];
12	  const B = CONFIG.bankX;
13	  for (let z = -2300; z < 2300; z += 14) {
14	    if (Math.abs(z) < 26 || Math.abs(z - CONFIG.ttl.z) < 24) continue;
15	    for (const s of [-1, 1]) {
16	      const x = s * (B + 9 + rand() * 12);
17	      ((Math.round(z / 14) % 3 === 0) ? palms : round).push([x, z]);
18	    }
19	  }
20	  for (const [x0, x1] of [[-1880, -345], [345, 1460]]) for (let x = x0; x < x1; x += 16) {
21	    for (const s of [-1, 1]) (x > 1200 ? palms : round).push([x + rand() * 3, s * 21.5]);
22	  }
23	  for (let i = 0; i < 160; i++) { // công viên hai đầu cầu
24	    const s = i % 2 ? 1 : -1; round.push([s * (345 + rand() * 120), (rand() < 0.5 ? -1 : 1) * (32 + rand() * 120)]);
25	  }
26	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3(), col = new THREE.Color();
27	  const trunkGeo = new THREE.CylinderGeometry(0.22, 0.35, 1, 6).translate(0, 0.5, 0);
28	  const t1 = new THREE.InstancedMesh(trunkGeo, MAT.trunk, round.length);
29	  const c1 = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 10, 8), MAT.leaf, round.length);
30	  round.forEach(([x, z], i) => {
31	    const h = 3 + rand() * 2.5, r = 2.4 + rand() * 1.8;
32	    m.compose(v.set(x, CONFIG.landY, z), q, s.set(1, h, 1)); t1.setMatrixAt(i, m);
33	    m.compose(v.set(x, CONFIG.landY + h + r * 0.6, z), q, s.set(r, r * 0.85, r)); c1.setMatrixAt(i, m);
34	    col.setHSL(0.27 + rand() * 0.06, 0.45, 0.35 + rand() * 0.12); c1.setColorAt(i, col);
35	  });
36	  const t2 = new THREE.InstancedMesh(trunkGeo, MAT.trunk, palms.length);
37	  const c2 = new THREE.InstancedMesh(new THREE.ConeGeometry(1, 1, 9, 1, true), MAT.palm, palms.length);
38	  palms.forEach(([x, z], i) => {
39	    const h = 8 + rand() * 4;
40	    m.compose(v.set(x, CONFIG.landY, z), q, s.set(0.8, h, 0.8)); t2.setMatrixAt(i, m);
41	    m.compose(v.set(x, CONFIG.landY + h + 0.3, z), q, s.set(3.8, 1.6, 3.8)); c2.setMatrixAt(i, m);
42	  });
43	  scene.add(shadowed(t1, true, false), shadowed(c1, true, false), shadowed(t2, true, false), shadowed(c2, true, false));
44	}
45	export function buildStreetLamps() {
46	  const pos: [number, number, number, number][] = [];
47	  for (let x = -320; x <= 320; x += 32) for (const s of [-1, 1]) pos.push([x, deckY(x) + 0.25, s * 17.0, 8]);
48	  for (let z = -2300; z < 2300; z += 30) for (const s of [-1, 1]) if (Math.abs(z) > 30) pos.push([s * (CONFIG.bankX + 22), CONFIG.landY, z, 6]);
49	  for (const [x0, x1] of [[-1880, -345], [345, 1460]]) for (let x = x0; x < x1; x += 40) for (const s of [-1, 1]) pos.push([x, CONFIG.roadY + 0.2, s * 17.5, 8]);
50	  const poles = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.1, 0.14, 1, 6).translate(0, 0.5, 0), MAT.lampPole, pos.length);
51	  const bulbs = new THREE.InstancedMesh(new THREE.SphereGeometry(0.42, 8, 6), MAT.bulb, pos.length);
52	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3();
53	  pos.forEach(([x, y, z, h], i) => {
54	    m.compose(v.set(x, y, z), q, s.set(1, h, 1)); poles.setMatrixAt(i, m);
55	    m.compose(v.set(x, y + h + 0.2, z), q, s.set(1, 1, 1)); bulbs.setMatrixAt(i, m);
56	  });
57	  poles.castShadow = true; scene.add(poles, bulbs);
58	}
