function tag(g, part, pivot, fix, maskFn, seg = 0, pivot2 = 0) {
  const n = g.attributes.position.count, P = new Float32Array(n).fill(part), V = new Float32Array(n).fill(pivot), M = new Float32Array(n), F = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { M[i] = maskFn ? maskFn(g.attributes.position.getY(i)) : 0; F.set(fix, i * 3); }
  g.setAttribute('aPart', new THREE.BufferAttribute(P, 1)); g.setAttribute('aPivot', new THREE.BufferAttribute(V, 1)); g.setAttribute('aMask', new THREE.BufferAttribute(M, 1)); g.setAttribute('aFix', new THREE.BufferAttribute(F, 3));
  g.setAttribute('aSeg', new THREE.BufferAttribute(new Float32Array(n).fill(seg), 1)); g.setAttribute('aPivot2', new THREE.BufferAttribute(new Float32Array(n).fill(pivot2), 1));
  return g.index ? g.toNonIndexed() : g;
}
const SHOE = hex(0x2a2a2e);
function personGeo() {
  const shirt = () => 1, pants = () => 2, cap = (r, l) => new THREE.CapsuleGeometry(r, l, 3, 7), HIP = 0.86, KNEE = 0.46, SHO = 1.37, ELB = 1.1, parts = [
    tag(cap(0.15, 0.3).scale(0.78, 1, 1.18).translate(0, 1.12, 0), 0, 0, SKIN, shirt),          // thân
    tag(new THREE.SphereGeometry(0.115, 10, 8).translate(0, 1.54, 0), 0, 0, SKIN),              // đầu
    tag(new THREE.SphereGeometry(0.123, 10, 6, 0, 6.3, 0, 1.75).translate(-0.018, 1.553, 0), 0, 0, HAIR), // tóc
    tag(new THREE.ConeGeometry(0.31, 0.17, 12).translate(0, 1.7, 0), 5, 0, HAT),                // nón lá
    tag(new THREE.BoxGeometry(0.13, 0.32, 0.25).translate(-0.18, 1.17, 0), 6, 0, PACK),         // ba lô
  ];
  for (const [side, leg, arm] of [[1, 1, 3], [-1, 2, 4]]) {
    parts.push(tag(cap(0.072, 0.28).translate(0, 0.66, side * 0.085), leg, HIP, SKIN, pants));                       // đùi
    parts.push(tag(cap(0.058, 0.3).translate(0, 0.25, side * 0.085), leg, HIP, SKIN, pants, 1, KNEE));               // ống chân
    parts.push(tag(new THREE.BoxGeometry(0.23, 0.07, 0.095).translate(0.045, 0.035, side * 0.085), leg, HIP, SHOE, null, 1, KNEE)); // giày
    parts.push(tag(cap(0.05, 0.18).translate(0, 1.235, side * 0.225), arm, SHO, SKIN, shirt));                       // bắp tay (áo cộc tay)
    parts.push(tag(cap(0.042, 0.2).translate(0, 0.96, side * 0.225), arm, SHO, SKIN, null, 1, ELB));                 // cẳng tay
  }
  return merge(parts);
}
const uT = { value: 0 };
function patchPerson(mat, withColor) {
  mat.onBeforeCompile = (sh) => {
    sh.uniforms.uT = uT;
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', `#include <common>
        attribute float aPart; attribute float aPivot; attribute float aMask; attribute vec3 aFix; attribute vec4 aVar; attribute vec3 aPants; attribute float aSeg; attribute float aPivot2; uniform float uT;
        float pFlag(float b) { return mod(floor(aVar.z / b), 2.0); }
        // x: góc khớp gốc (hông / vai), y: góc khớp giữa (gối / khuỷu). Dương = đưa về phía trước.
        vec2 pAngles() {
          float A = aVar.y, ph = uT * aVar.w + aVar.x, run = smoothstep(0.42, 0.6, A);
          if (aPart > 0.5 && aPart < 2.5) { float f = aPart < 1.5 ? ph : ph + 3.14159;
            float sw = max(0.0, cos(f - 0.35));                                      // pha đưa chân lên trước: gập gối
            return vec2(A * (sin(f) + 0.12), -(A * (2.0 + run * 1.2) * sw * sw + 0.06 * step(0.01, A))); }
          if (aPart > 2.5 && aPart < 4.5) { float f = aPart < 3.5 ? ph + 3.14159 : ph;
            if (aPart > 3.5 && pFlag(4.0) > 0.5) return vec2(1.0, 1.05);             // giơ tay chụp ảnh
            return vec2(A * (0.65 + run * 0.5) * sin(f) - 0.05, 0.16 + run * 1.25 + A * 0.35 * max(0.0, sin(f))); }
          return vec2(0.0);
        }
        vec2 pRot(vec2 p, float a) { float c = cos(a), s = sin(a); return vec2(p.x * c - p.y * s, p.x * s + p.y * c); }`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        vec2 pa = pAngles();
        if (aSeg > 0.5) transformed.xy = pRot(transformed.xy - vec2(0.0, aPivot2), pa.y) + vec2(0.0, aPivot2);
        transformed.xy = pRot(transformed.xy - vec2(0.0, aPivot), pa.x) + vec2(0.0, aPivot);
        if (aPart > 4.5 && aPart < 5.5 && pFlag(1.0) < 0.5) transformed *= 0.0;
        if (aPart > 5.5 && pFlag(2.0) < 0.5) transformed *= 0.0;
        float pph = uT * aVar.w + aVar.x;
        transformed.y += (0.022 * cos(2.0 * pph) - 0.022) * step(0.01, aVar.y) * (1.0 + 2.0 * smoothstep(0.42, 0.6, aVar.y));   // nhún: thấp nhất khi hai chân dang rộng
        transformed.z += 0.018 * sin(pph) * step(0.01, aVar.y) * smoothstep(0.3, 1.6, transformed.y);                            // lắc vai nhẹ sang hai bên`);
    if (withColor) sh.vertexShader = sh.vertexShader
      .replace('#include <beginnormal_vertex>', '#include <beginnormal_vertex>\n vec2 pn = pAngles(); objectNormal.xy = pRot(objectNormal.xy, pn.x + (aSeg > 0.5 ? pn.y : 0.0));')
      .replace('#include <color_vertex>', 'vColor = aMask < 0.5 ? aFix : (aMask < 1.5 ? instanceColor : aPants);');
  };
  return mat;
